/* HEXA BATTLEGROUNDS setup — PART 31 OF 57. Run parts in order. Safe to re-run. */ create or replace function _autopilot(p_arena uuid) returns boolean language plpgsql as $$ declare a arenas; v_ev uuid; v_fam text; v_n int; v_pos int; v_fm int; st text[]; v_open int; v_res boolean := false; v_stat jsonb; begin if coalesce(current_setting('hb.in_auto', true), '') = '1' then return false; end if; select * into a from arenas where id = p_arena; if a.id is null or not a.autopilot or a.paused or a.phase = 'ended' then return false; end if; v_ev := a.event_id; perform set_config('hb.in_auto', '1', true); begin v_fam := case when a.phase in ('lobby', 'boarding') then 'boarding' when a.phase in ('shuttle', 'roles') then 'ride' when a.phase = 'play' then 'play' else 'fin' end; if split_part(coalesce(a.auto_step, ''), ':', 1) <> v_fam then perform _auto_resync(a.id); select * into a from arenas where id = p_arena; v_res := true; end if; if a.phase = 'lobby' then if exists (select 1 from teams where arena_id = a.id and ready) then perform _host_exec(v_ev, a.id, 'open_boarding', '{}'::jsonb, 'autopilot'); update arenas set auto_step = 'boarding', auto_next_at = now() + _secs(coalesce(_cfg(v_ev, 'boarding_seconds'), 18)) where id = a.id; insert into audit_log(event_id, arena_id, actor, action) values (v_ev, a.id, 'autopilot', 'open_boarding'); v_res := true; end if; elsif a.phase = 'boarding' then if a.auto_next_at is not null and now() >= a.auto_next_at then if exists (select 1 from teams where arena_id = a.id and ready) then perform _host_exec(v_ev, a.id, 'drive', '{}'::jsonb, 'autopilot'); update arenas set auto_step = 'ride', auto_next_at = null where id = a.id; insert into audit_log(event_id, arena_id, actor, action) values (v_ev, a.id, 'autopilot', 'drive'); else update arenas set auto_next_at = now() + interval '10 seconds' where id = a.id; end if; v_res := true; end if; elsif a.phase = 'play' then if a.match_phase > a.auto_story then st := _auto_story(a.match_phase); update arenas set auto_story = a.match_phase where id = a.id; perform _host_exec(v_ev, a.id, 'story', jsonb_build_object('title', st[1], 'body', st[2]), 'autopilot'); if a.match_phase in (2, 3) then perform _host_exec(v_ev, a.id, 'bargain', jsonb_build_object('title', 'Squad 00 offers a deal', 'body', case a.match_phase when 2 then 'Take our coins now. All it costs is a little of your squad''s trust.' else 'A bigger offer. Accept, and the threat on this map rises.' end, 'coins', case a.match_phase when 2 then 60 else 90 end, 'threat', 1, 'trust', case a.match_phase when 2 then -5 else -10 end, 'minutes', 2), 'autopilot'); end if; v_res := true; end if; v_fm := _auto_finale_minute(v_ev); if a.play_started_at is not null and now() >= a.play_started_at + make_interval(mins => v_fm) then perform _host_exec(v_ev, a.id, 'begin_finale', '{}'::jsonb, 'autopilot'); update arenas set auto_step = 'fin:0', auto_next_at = now() + interval '12 seconds', match_phase = 5, phase_started_at = now(), phase_next_at = null, overlay = overlay || jsonb_build_object('match', jsonb_build_object('phase', 5, 'started_at', now(), 'next_at', null, 'zone_target', 5)) where id = a.id; perform _feed(a.id, 'phase.started', jsonb_build_object('phase', 5)); insert into audit_log(event_id, arena_id, actor, action) values (v_ev, a.id, 'autopilot', 'begin_finale'); v_res := true; end if; elsif a.phase in ('finale', 'results') then v_n := greatest(1, coalesce(_cfg(v_ev, 'finale_battles'), 2)); if a.sync_round_id is not null then select count(*) into v_open from mission_instances where sync_round_id = a.sync_round_id and status = 'active'; if v_open = 0 then perform _host_exec(v_ev, a.id, 'close_sync', '{}'::jsonb, 'autopilot'); v_res := true; end if; elsif a.auto_next_at is null then update arenas set auto_next_at = now() + interval '10 seconds' where id = a.id; v_res := true; elsif now() >= a.auto_next_at then v_pos := _auto_fin_pos(a.id); if v_pos < 2 + v_n then perform _host_exec(v_ev, a.id, 'finale_stage', jsonb_build_object('stage', case when v_pos = 0 then 'A' when v_pos = 1 then 'B' else 'C' end), 'autopilot'); perform _host_exec(v_ev, a.id, 'launch_sync', jsonb_build_object('kind', case when v_pos = 0 then 'finale_entry' when v_pos = 1 then 'finale_exchange' else 'finale_battle' end), 'autopilot'); update arenas set auto_next_at = null where id = a.id; elsif v_pos = 2 + v_n then perform _host_exec(v_ev, a.id, 'reveal_squad00', '{}'::jsonb, 'autopilot'); update arenas set auto_next_at = now() + interval '30 seconds' where id = a.id; elsif v_pos = 3 + v_n then perform _host_exec(v_ev, a.id, 'finale_stage', jsonb_build_object('stage', 'E'), 'autopilot'); perform _host_exec(v_ev, a.id, 'launch_sync', jsonb_build_object('kind', 'final_code'), 'autopilot'); update arenas set auto_next_at = null where id = a.id; elsif v_pos = 4 + v_n then perform _host_exec(v_ev, a.id, 'lock_results', '{}'::jsonb, 'autopilot'); update arenas set auto_next_at = now() + interval '15 seconds' where id = a.id; elsif v_pos = 5 + v_n then perform _host_exec(v_ev, a.id, 'reveal_winner', '{}'::jsonb, 'autopilot'); update arenas set auto_next_at = now() + interval '20 seconds' where id = a.id; elsif v_pos = 6 + v_n then if not exists (select 1 from arenas x where x.event_id = v_ev and not x.winner_revealed and exists (select 1 from teams where arena_id = x.id and ready)) then update events set grand_revealed = true where id = v_ev; perform _ping_arena(x.id, 'grand') from arenas x where x.event_id = v_ev; end if; end if; if v_pos < 6 + v_n or (select grand_revealed from events where id = v_ev) then insert into audit_log(event_id, arena_id, actor, action, args) values (v_ev, a.id, 'autopilot', 'finale_step', jsonb_build_object('step', _auto_step_name(v_pos, v_n))); v_res := true; end if; end if; update arenas set auto_step = 'fin:' || _auto_fin_pos(a.id) where id = a.id; end if; v_stat := _auto_status(a.id) - 'step'; update arenas set overlay = overlay || jsonb_build_object('auto', v_stat) where id = a.id and overlay -> 'auto' is distinct from v_stat; if found then v_res := true; end if; exception when others then perform set_config('hb.in_auto', '', true); if not exists (select 1 from audit_log where arena_id = a.id and actor = 'autopilot' and not ok and at > now() - interval '30 seconds') then insert into audit_log(event_id, arena_id, actor, action, ok, error) values (v_ev, a.id, 'autopilot', 'step', false, sqlerrm); end if; return false; end; perform set_config('hb.in_auto', '', true); if v_res then perform _ping_arena(a.id, 'auto'); end if; return v_res; end $$; create or replace function _defaults() returns jsonb language sql immutable as $$ select jsonb_build_object( 'pts_standard', 100, 'pts_hard', 150, 'pts_battle', 125, 'pts_airdrop', 75, 'pts_relay_bonus', 25, 'pts_relocation', 40, 'pen_recovery', 40, 'finale_max', 300, 'finale_entry_max', 200, 'finale_exchange_max', 200, 'hp_max', 100, 'hp_respawn', 50, 'dmg_fail', 10, 'dmg_zone', 15, 'shield_max', 60, 'shuttle_seconds', 10, 'roles_seconds', 15, 'bus_size', 3, 'arena_size', 15, 'attack_cooldown', 90, 'protect_seconds', 120, 'recovery_seconds', 120, 'zone_warning', 60, 'airdrop_window', 180, 'airdrop_interval', 0, 'intel_fallback', 90, 'relay_chance', 20, 'hint_cost', 0, 'alliance_minutes', 10, 'alliance_cost', 10, 'chat_limit', 6, 'drop_seconds', 8, 'visit_missions', 2, 'zone_auto', 0, 'zone_schedule', '20,40,55,70,85', 'sync_seconds', 0, 'auto_pacing', 0, 'phase_schedule', '2,12,30,50', 'duel_phase', 2, 'mission_time_pct', 100, 'pin_length', 6, 'move_speed', 25, 'loc_radius', 35, 'engage_range', 60, 'zone_tick_seconds', 6, 'zone_tick_damage', 4, 'red_interval', 0, 'red_warning', 20, 'red_damage', 30, 'red_radius', 80 ) || jsonb_build_object( 'reveal_pct', 50, 'boarding_seconds', 18, 'finale_minute', 0, 'finale_battles', 2 ) $$; create or replace function _tick(p_arena uuid, p_force boolean default false) returns boolean language plpgsql as $$ declare a arenas; r record; tm teams; c float8[]; xy float8[]; v_tick int; v_bucket bigint; v_changed boolean := false; v_sched text[]; v_next int; v_at timestamptz; v_target int; begin if not pg_try_advisory_xact_lock(hashtext('tick' || p_arena::text)) then return false; end if; select * into a from arenas where id = p_arena; if a.id is null or a.paused then return false; end if; if not p_force and a.last_tick_at is not null and a.last_tick_at > now() - interval '800 milliseconds' then return false; end if; update arenas set last_tick_at = now() where id = p_arena; if a.phase = 'shuttle' and now() >= a.shuttle_arrive_at then update arenas set phase = 'roles', roles_deadline = now() + _secs(_cfg(a.event_id, 'roles_seconds')) where id = p_arena; update teams set location_id = 'gate_1', state = 'idle' where arena_id = p_arena and ready; perform _feed(p_arena, 'shuttle.arrived', '{}'::jsonb); v_changed := true; end if; select * into a from arenas where id = p_arena; if a.phase = 'roles' and now() >= a.roles_deadline then perform _finalize_roles(p_arena); update arenas set phase = 'play', play_started_at = now() where id = p_arena; perform _feed(p_arena, 'role.assignment.completed', '{}'::jsonb); perform _feed(p_arena, 'map.revealed', '{}'::jsonb); perform _set_match_phase(p_arena, 0); v_changed := true; end if; select * into a from arenas where id = p_arena; if a.phase not in ('play', 'finale') then if a.autopilot and _autopilot(p_arena) then v_changed := true; end if; if v_changed then perform _ping_arena(p_arena, 'phase'); end if; return v_changed; end if; for r in select id from teams where arena_id = p_arena and state = 'traveling' and travel_arrive_at <= now() loop perform _arrive(r.id); v_changed := true; end loop; for r in select id from battles where arena_id = p_arena and status = 'active' and deadline <= now() loop perform _resolve_battle(r.id, null); v_changed := true; end loop; for r in select id, kind, sync_round_id from mission_instances where arena_id = p_arena and status = 'active' and deadline <= now() and kind <> 'battle' loop perform _fail(r.id, 'expired'); v_changed := true; end loop; for r in select id from teams where arena_id = p_arena and state = 'recovery' and recovery_deadline <= now() loop perform _respawn(r.id, 'timeout'); v_changed := true; end loop; for r in select id from sync_rounds where arena_id = p_arena and status = 'active' and deadline <= now() loop update sync_rounds set status = 'closed' where id = r.id; update arenas set sync_round_id = null where id = p_arena and sync_round_id = r.id; perform _feed(p_arena, 'sync.closed', '{}'::jsonb); v_changed := true; end loop; select * into a from arenas where id = p_arena; if a.phase = 'play' and a.match_phase < 4 and a.phase_next_at is not null and now() >= a.phase_next_at then perform _set_match_phase(p_arena, a.match_phase + 1); v_changed := true; end if; select * into a from arenas where id = p_arena; if a.phase = 'play' and not a.zone_hold and a.zone_next_at is null and a.zone_stage < 5 then v_target := _phase_zone_target(a.match_phase); if a.zone_stage < v_target then update arenas set zone_next_at = now() + _secs(_cfg(a.event_id, 'zone_warning')) where id = p_arena; perform _feed(p_arena, 'zone.warning', jsonb_build_object('stage', a.zone_stage + 1)); v_changed := true; end if; end if; select * into a from arenas where id = p_arena; if a.phase = 'play' and _cfg(a.event_id, 'zone_auto') = 1 and a.zone_next_at is null and a.zone_stage < 5 and not a.zone_hold then v_sched := string_to_array(_cfg_text(a.event_id, 'zone_schedule'), ','); v_next := trim(v_sched[a.zone_stage + 1])::int; if v_next is not null then v_at := a.play_started_at + make_interval(mins => v_next); if now() >= v_at - _secs(_cfg(a.event_id, 'zone_warning')) then update arenas set zone_next_at = greatest(v_at, now() + interval '10 seconds') where id = p_arena; perform _feed(p_arena, 'zone.warning', jsonb_build_object('stage', a.zone_stage + 1)); v_changed := true; end if; end if; end if; select * into a from arenas where id = p_arena; if a.zone_next_at is not null and now() >= a.zone_next_at then perform _zone_advance(p_arena); v_changed := true; end if; select * into a from arenas where id = p_arena; if a.phase = 'play' then c := _zone_circle(a.event_id, a.zone_stage); v_tick := greatest(2, _cfg(a.event_id, 'zone_tick_seconds')); v_bucket := floor(extract(epoch from now()) / v_tick)::bigint; for tm in select * from teams where arena_id = p_arena and ready and state <> 'recovery' and (zone_hit_at is null or zone_hit_at <= now() - _secs(v_tick)) loop xy := _team_xy(tm); if not _in_circle(c, xy[1], xy[2]) then update teams set zone_hit_at = now() where id = tm.id; perform _damage(tm.id, _cfg(a.event_id, 'zone_tick_damage'), 'zone_damage', 'zt-' || v_bucket, 'Outside the safe zone'); perform _ping_team(tm.id, 'zone'); v_changed := true; end if; end loop; end if; select * into a from arenas where id = p_arena; if a.red_at is not null and now() >= a.red_at then perform _red_strike(p_arena); v_changed := true; elsif a.phase = 'play' and a.red_at is null and a.match_phase >= 2 and _cfg(a.event_id, 'red_interval') > 0 and coalesce(a.last_red_at, a.phase_started_at, a.play_started_at) < now() - make_interval(mins => _cfg(a.event_id, 'red_interval')) then perform _red_spawn(p_arena); v_changed := true; end if; if a.phase = 'play' and _cfg(a.event_id, 'airdrop_interval') > 0 and coalesce(a.last_airdrop_at, a.play_started_at) < now() - make_interval(mins => _cfg(a.event_id, 'airdrop_interval')) then perform _spawn_airdrop(p_arena, null, (array['common', 'common', 'rare', 'mystery', 'intel', 'cursed', 'legendary'])[1 + floor(random() * 7)::int]); v_changed := true; end if; update airdrops set status = 'expired' where arena_id = p_arena and status = 'open' and expires_at <= now(); if found then v_changed := true; end if; update mission_instances mi set status = 'cancelled' from airdrops ad where mi.airdrop_id = ad.id and ad.status = 'expired' and mi.status = 'active'; update alliances set status = 'expired' where arena_id = p_arena and status = 'proposed' and created_at < now() - interval '2 minutes'; update alliances set status = 'ended' where arena_id = p_arena and status = 'active' and expires_at <= now(); select * into a from arenas where id = p_arena; if a.autopilot and _autopilot(p_arena) then v_changed := true; end if; if v_changed then perform _zone_publish(p_arena); perform _ping_arena(p_arena, 'tick'); end if; return v_changed; end $$; create or replace function _shift_arena(p_arena uuid, p_delta interval) returns void language plpgsql as $$ begin update arenas set shuttle_departed_at = shuttle_departed_at + p_delta, shuttle_arrive_at = shuttle_arrive_at + p_delta, roles_deadline = roles_deadline + p_delta, play_started_at = play_started_at + p_delta, zone_next_at = zone_next_at + p_delta, last_airdrop_at = last_airdrop_at + p_delta, phase_started_at = phase_started_at + p_delta, phase_next_at = phase_next_at + p_delta, red_at = red_at + p_delta, last_red_at = last_red_at + p_delta, auto_next_at = auto_next_at + p_delta, overlay = case when overlay ? 'match' then jsonb_set(overlay, '{match,next_at}', coalesce(to_jsonb((overlay #>> '{match,next_at}')::timestamptz + p_delta), 'null'::jsonb)) else overlay end where id = p_arena; update mission_instances set deadline = deadline + p_delta, fallback_at = fallback_at + p_delta, started_at = started_at + p_delta where arena_id = p_arena and status = 'active'; update battles set deadline = deadline + p_delta, started_at = started_at + p_delta where arena_id = p_arena and status = 'active'; update sync_rounds set deadline = deadline + p_delta, started_at = started_at + p_delta where arena_id = p_arena and status = 'active'; update airdrops set expires_at = expires_at + p_delta, spawned_at = spawned_at + p_delta where arena_id = p_arena and status = 'open'; update alliances set expires_at = expires_at + p_delta, created_at = created_at + p_delta where arena_id = p_arena and status in ('proposed', 'active'); update story_events set expires_at = expires_at + p_delta where arena_id = p_arena and expires_at > now(); update teams set zone_hit_at = zone_hit_at + p_delta, travel_started_at = travel_started_at + p_delta, travel_arrive_at = travel_arrive_at + p_delta, recovery_deadline = recovery_deadline + p_delta, attack_cooldown_until = attack_cooldown_until + p_delta, protected_until = protected_until + p_delta, jammed_until = jammed_until + p_delta, scan_until = scan_until + p_delta where arena_id = p_arena; perform _zone_publish(p_arena); end $$;
